// FIX226B_K3_DYN_W128CH16_W64CH32_APPLIED
// FIX223_FIXED_BUDGET_MULTI_OP_CACHE_APPLIED
// FIX213_WR_DATA_PREACC_PIPE: split lane_idx/acc_current -> wr_pipe_data timing path.
// conv2d_ddr_core.v
// DDR-weight version: weights/bias are fetched from the same byte DDR interface.
// This removes hard-coded weight ROMs from FPGA fabric.

module conv2d_ddr_core #(
    parameter DATA_W    = 8,
    parameter ADDR_W    = 32,
    parameter ACC_W  = 32,
    parameter MAX_W_NUM = 131072,
    parameter MAX_B_NUM = 512,
    parameter MAC_LANES = 64  // FIX180_FULL_MAC64_GROUP64: experimental true MAC64/group64
)(
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire                    start,

    input  wire [15:0]             in_ch,
    input  wire [15:0]             out_ch,
    input  wire [15:0]             in_w,
    input  wire [15:0]             in_h,
    input  wire [15:0]             out_w,
    input  wire [15:0]             out_h,
    input  wire [3:0]              k_size,
    input  wire [3:0]              stride,
    input  wire [3:0]              pad,

    input  wire [ADDR_W-1:0]       input_base,
    input  wire [ADDR_W-1:0]       output_base,
    input  wire [ADDR_W-1:0]       weight_base,
    input  wire [ADDR_W-1:0]       bias_base,
    input  wire                    quad_weight_en, // FIX164_QUAD_SCOPE_DIAG

    // Fixed-point requantization shift applied before storing feature maps.
    // This is NOT a full per-layer quantization table; tune/replace with real scales later.
    input  wire [4:0]              out_shift,
    input  wire [31:0]             out_mult,
    input  wire [4:0]              out_mult_shift,
    input  wire                    act_silu_en,

    // Scale-aware SiLU path:
    // acc_requant is q_conv using conv output scale. Convert q_conv -> Q4.4,
    // run existing Q4.4 SiLU LUT, then convert Q4.4 -> output activation scale.
    input  wire [7:0]              silu_lut_id,
    input  wire [31:0]             silu_in_mult,
    input  wire [4:0]              silu_in_shift,
    input  wire [31:0]             silu_out_mult,
    input  wire [4:0]              silu_out_shift,

    output wire                    mem_rd_req,
    output wire [ADDR_W-1:0]       mem_rd_addr,
    input  wire                    mem_rd_ready,
    input  wire                    mem_rd_valid,
    input  wire [DATA_W-1:0]       mem_rd_data,

    // FIX164_MAC4_WEIGHT_PACK32: 32-bit read sideband used only for MAC4 quad-interleaved weights.
    output wire                    mem_rd32_req,
    output wire [ADDR_W-1:0]       mem_rd32_addr,
    input  wire                    mem_rd32_ready,
    input  wire                    mem_rd32_valid,
    input  wire [31:0]             mem_rd32_data,

    // FIX164_MAC8_VECTOR_PACK64: 64-bit read sideband for packed MAC8/oct weights.
    output wire                    mem_rd64_req,
    output wire [ADDR_W-1:0]       mem_rd64_addr,
    input  wire                    mem_rd64_ready,
    input  wire                    mem_rd64_valid,
    input  wire [63:0]             mem_rd64_data,

    output wire                    mem_wr_req,
    output wire [ADDR_W-1:0]       mem_wr_addr,
    output wire [DATA_W-1:0]       mem_wr_data,
    input  wire                    mem_wr_ready,

    // FIX_CONV_WR64_PACKER: optional 8-byte packed output writes for CHW layout.
    output wire                    mem_wr64_req,
    output wire [ADDR_W-1:0]       mem_wr64_addr,
    output wire [63:0]             mem_wr64_data,
    input  wire                    mem_wr64_ready,

    output wire                    busy,
    output wire                    done,

    output wire                    out_valid,
    output wire signed [ACC_W-1:0] out_data,

    output wire                    final_wr_en,
    output wire [ADDR_W-1:0]       final_wr_addr,
    output wire [DATA_W-1:0]       final_wr_data,

    // FIX164_MAC16_DETAILED_PROFILER: expose conv FSM state to APB profiler.
    output wire [4:0]              prof_state
);

    localparam S_IDLE      = 4'd0;
    localparam S_BIAS_REQ  = 4'd1;
    localparam S_BIAS_WAIT = 4'd2;
    localparam S_MAC       = 4'd3;
    localparam S_W_REQ     = 4'd4;
    localparam S_W_WAIT    = 4'd5;
    localparam S_ACT_REQ   = 4'd6;
    localparam S_ACT_WAIT  = 4'd7;
    localparam S_WRITE     = 4'd8;
    localparam S_DONE      = 4'd9;
    localparam S_W4_REQ    = 4'd10; // FIX164_MAC4_WEIGHT_PACK32: request one 32-bit weight word for lanes 0..3
    localparam S_W4_WAIT   = 4'd11; // FIX164_MAC4_WEIGHT_PACK32: latch 4 weight bytes
    localparam S_W8_REQ    = 4'd12; // FIX164_MAC8_VECTOR_PACK64: request one 64-bit weight word for lanes 0..7
    localparam S_W8_WAIT   = 4'd13; // FIX164_MAC8_VECTOR_PACK64: latch 8 weight bytes
    localparam S_BIAS_CHECK = 4'd14; // FIX164_MAC16_BIAS_CACHE_SAFE: reuse cached bias for same OC group
    localparam S_WRITE_PREP = 5'd15; // FIX164_MAC16_WRITE_PREP_PIPE: register write addr/data before bridge
    // FIX164_CONV_ALL_WEIGHT_CACHE: cache the current CONV oc-group weights once,
    // then reuse them for all output pixels of that oc-group.  This attacks the
    // dominant S_W64_WAIT DDR-read bottleneck without changing the SD weight file.
    localparam S_WCACHE_CHECK     = 5'd16;
    localparam S_WCACHE_LOAD_REQ  = 5'd17;
    localparam S_WCACHE_LOAD_WAIT = 5'd18;
    localparam S_WCACHE_USE_REQ   = 5'd19;
    localparam S_WCACHE_USE_WAIT  = 5'd20;
    localparam S_L0_FILL_REQ      = 5'd21; // FIX185B_L0_INPUT_LINEBUF: fill one input-image row
    localparam S_L0_FILL_WAIT     = 5'd22; // FIX185B_L0_INPUT_LINEBUF
    localparam S_ACT_CACHE_HIT    = 5'd23; // FIX185B_L0_INPUT_LINEBUF: use cached activation byte
    localparam S_K3_FILL_REQ      = 5'd24; // FIX189E_MULTI_K3_ACT_LINEBUF: fill one k=3 activation row
    localparam S_K3_FILL_WAIT     = 5'd25; // FIX189E_MULTI_K3_ACT_LINEBUF
    localparam S_K1_FILL64_REQ    = 5'd26; // FIX201B_K1_LINEFILL_RD64
    localparam S_K1_FILL64_WAIT   = 5'd27; // FIX201B_K1_LINEFILL_RD64
    localparam S_K1_FILL64_DRAIN  = 5'd28; // FIX201B_K1_LINEFILL_RD64
    localparam S_WRITE_PREP2      = 5'd29; // FIX213_WR_DATA_PREACC_PIPE: split lane_idx->wr_pipe_data timing path
    localparam S_WR64_FLUSH       = 5'd30; // FIX_CONV_WR64_PACKER: flush one 64-bit word per valid lane
    localparam S_WRITE_PREP3      = 5'd31; // FIX_CONV_WR64_PACKER_TIMING: registered output byte -> wr64 buffer
    // Timing pipeline for the legacy byte-at-a-time weight path.  This state
    // registers weight_base + w_index before S_W_REQ asserts mem_rd_req,
    // breaking the active_k/oc/lane_idx -> AXI bridge address critical path.
    localparam S_W_ADDR_PREP      = 6'd32;

    reg [5:0] state;

    // FIX164_MAC16_DETAILED_PROFILER: current state code exported to wrapper/APB.
    // S_W_ADDR_PREP is intentionally reported as state 0 to the legacy
    // five-bit profiler; this affects diagnostics only, never control/data.
    assign prof_state = state[4:0]; // FIX165_PROF_5BIT_WCACHE: export legacy five-bit state code

    assign busy = (state != S_IDLE) && (state != S_DONE);
    assign done = (state == S_DONE);

    integer oc;
    integer oy;
    integer ox;
    integer ic;
    integer ky;
    integer kx;

    // FIX164_VECTOR_MAC_LANES4_PHASE1: scalable vector MAC lanes.
    // Phase 1 uses MAC_LANES=4, but this structure is parameterized for 8/16/32/128 later.
    reg signed [ACC_W-1:0] acc_vec [0:MAC_LANES-1];
    reg signed [7:0]       w_vec   [0:MAC_LANES-1];
    reg [7:0]              lane_idx;
    reg [7:0]              weight_beat_idx; // FIX164_MAC16_VECTOR_MULTIBEAT
    integer                lane_loop_i;
    integer                l0_reset_i; // FIX185B_L0_INPUT_LINEBUF
    integer                k3_reset_i; // FIX189E_MULTI_K3_ACT_LINEBUF

    // FIX164_CONV_ALL_WEIGHT_CACHE:
    // One cache per current CONV oc-group.  For MAC16, worst YOLOv5n group is
    // 256*3*3*16 = 36864 bytes = 4608 x 64-bit beats, so 8192 beats is safe.
    localparam integer WCACHE_BYTES_MAX  = 147456; // FIX180_FULL_MAC64_GROUP64: 256*3*3*64 bytes
    // FIX182_MAC64_WCACHE_PACK512_NODUP:
    // For MAC64, one tap = 64 weights = 512 bits. Store one full tap per cache line.
    // This keeps the same total cache capacity, but avoids 8 FSM cycles of 64-bit unpack per tap.
    localparam integer WCACHE_LINE_BYTES = 64;
    localparam integer WCACHE_BEATS_MAX  = WCACHE_BYTES_MAX / 8;
    localparam integer WCACHE_TAPS_MAX   = WCACHE_BYTES_MAX / WCACHE_LINE_BYTES;
    reg [511:0]            wcache512 [0:WCACHE_TAPS_MAX-1];
    reg                    wcache_valid;
    reg [31:0]             wcache_oc;
    reg [31:0]             wcache_total_beats;
    reg [31:0]             wcache_load_beat;
    reg [31:0]             wcache_rd_beat;
    reg [511:0]            wcache_rd_data512;

    reg [31:0]             bias_r;
    reg [1:0]              bias_byte_idx;

    // FIX164_MAC16_BIAS_CACHE_SAFE: bias is constant for all pixels of the same OC group.
    // Cache the MAC_LANES bias values after first load, then reload acc_vec from cache
    // on subsequent output pixels with the same oc. Cache is cleared on every start.
    reg                    bias_cache_valid;
    reg [31:0]             bias_cache_oc;
    reg signed [ACC_W-1:0] bias_cache_vec [0:MAC_LANES-1];

    // FIX164_MAC16_WRITE_PREP_PIPE: cut long path from acc/requant/SiLU output to bridge wr_data_r.
    reg                    wr_pipe_valid;
    reg [ADDR_W-1:0]       wr_pipe_addr;
    reg [DATA_W-1:0]       wr_pipe_data;
    reg [ADDR_W-1:0]       w_addr_pipe;
    reg signed [ACC_W-1:0] wr_acc_pre; // FIX213_WR_DATA_PREACC_PIPE
    reg [DATA_W-1:0]       wr_out_byte_pre; // FIX_CONV_WR64_PACKER_TIMING: cut wr_acc_pre/SiLU -> conv_wr64_buf W_DATA path

    // FIX_CONV_WR64_PACKER:
    // CHW-safe packer. Each MAC lane represents one OC channel, whose output
    // bytes are contiguous only along x. Therefore pack x[0..7] per lane/OC,
    // not lane0..lane7 together.
    reg [63:0]             conv_wr64_buf [0:MAC_LANES-1];
    reg [7:0]              conv_wr64_flush_lane;

    wire signed [31:0] iy_calc;
    wire signed [31:0] ix_calc;

    assign iy_calc = (oy * stride) + ky - pad;
    assign ix_calc = (ox * stride) + kx - pad;

    wire in_bound;
    assign in_bound = (iy_calc >= 0) && (iy_calc < in_h) &&
                      (ix_calc >= 0) && (ix_calc < in_w);

    // FIX185B_L0_INPUT_LINEBUF:
    // Strong L0-only activation reuse.  L0 is the image-input conv
    // (3x320x320, k=6, stride=2).  Instead of re-reading the same image
    // pixels from DDR for many overlapping 6x6 windows, keep 8 rolling
    // rows per input channel in on-chip RAM.  On a row miss, fill the
    // whole 320-byte row once; subsequent taps hit locally.
    localparam integer L0_LINE_W       = 256;
    localparam integer L0_LINE_ROWS    = 8;
    localparam integer L0_LINE_CH      = 3;
    localparam integer L0_LINE_COUNT   = L0_LINE_ROWS * L0_LINE_CH;
    localparam integer L0_LINE_ENTRIES = L0_LINE_COUNT * L0_LINE_W;

    reg [7:0]  l0_line_data  [0:L0_LINE_ENTRIES-1];
    reg [15:0] l0_line_tag_y [0:L0_LINE_COUNT-1];
    reg        l0_line_valid [0:L0_LINE_COUNT-1];

    reg [8:0]  l0_fill_x;
    reg [15:0] l0_fill_y;
    reg [1:0]  l0_fill_ic;
    reg [2:0]  l0_fill_slot;
    reg [4:0]  l0_fill_row_id;

    wire        l0_line_enable = (in_ch == 16'd3) && (in_w == 16'd256) &&
                                 (in_h == 16'd256) && (k_size == 4'd6) &&
                                 (stride == 4'd2);
    wire [15:0] l0_y_u = iy_calc[15:0];
    wire [8:0]  l0_x_u = ix_calc[8:0];
    wire [2:0]  l0_slot_w = iy_calc[2:0];
    wire [4:0]  l0_row_id_w = (ic[1:0] * L0_LINE_ROWS) + l0_slot_w;
    wire [12:0] l0_line_index_w = (l0_row_id_w * L0_LINE_W) + l0_x_u;
    wire        l0_line_active = l0_line_enable && in_bound && (ic < 3);
    wire        l0_line_hit = l0_line_active && l0_line_valid[l0_row_id_w] &&
                              (l0_line_tag_y[l0_row_id_w] == l0_y_u);
    wire        l0_line_miss = l0_line_active && !l0_line_hit;
    wire signed [7:0] l0_cached_act_s = l0_line_data[l0_line_index_w];

    wire [12:0] l0_fill_index = (l0_fill_row_id * L0_LINE_W) + l0_fill_x;
    wire [31:0] l0_fill_offset = (l0_fill_ic * (in_h * in_w)) +
                                  (l0_fill_y * in_w) + l0_fill_x;

    // FIX189E_MULTI_K3_ACT_LINEBUF:
    // Generic activation line buffer for early k=3 convs.
    // Covers op1/op5/op9-style convs and other k=3 convs with
    // in_ch<=32, in_w/in_h<=160, stride 1 or 2.
    // FIX226B_K3_DYN_W128CH16_W64CH32:
    // Same physical budget: 4*32*64 = 4*16*128 = 8192 entries.
    // Mode small maps: W64  x CH32.
    // Mode OP1/L1:     W128 x CH16.
    localparam integer K3_LINE_W_MAX   = 64;
    localparam integer K3_LINE_ROWS    = 4;
    localparam integer K3_LINE_CH_MAX  = 32;
    localparam integer K3_LINE_COUNT   = K3_LINE_ROWS * K3_LINE_CH_MAX;
    localparam integer K3_LINE_ENTRIES = K3_LINE_COUNT * K3_LINE_W_MAX;

    reg [7:0]  k3_line_data  [0:K3_LINE_ENTRIES-1];
    reg [15:0] k3_line_tag_y [0:K3_LINE_COUNT-1];

    wire k3_line_mode_w128_ch16 =
        (k_size == 4'd3) && (in_ch <= 16'd16) &&
        (in_w <= 16'd128) && (in_h <= 16'd128);

    wire [7:0] k3_line_w_eff  = k3_line_mode_w128_ch16 ? 8'd128 : 8'd64;
    wire [5:0] k3_line_ch_eff = k3_line_mode_w128_ch16 ? 6'd16  : 6'd32;
    reg        k3_line_valid [0:K3_LINE_COUNT-1];

    reg [7:0]  k3_fill_x;
    reg [15:0] k3_fill_y;
    reg [4:0]  k3_fill_ic;
    reg [1:0]  k3_fill_slot;
    reg [6:0]  k3_fill_row_id;
    reg [63:0] k1_fill64_data; // FIX201B_K1_LINEFILL_RD64
    reg [2:0]  k1_fill64_idx;  // FIX201B_K1_LINEFILL_RD64
    wire       k1_fill64_enable = (k_size == 4'd1) && (stride == 4'd1) && (pad == 4'd0) &&
                                  (in_w[2:0] == 3'd0) &&
                                  (((in_ch <= 16'd64)  && (in_w <= 16'd64) && (in_h <= 16'd64)) ||
                                   ((in_ch <= 16'd128) && (in_w <= 16'd32) && (in_h <= 16'd32)) || // FIX208C_K1_128x32_ONLY
                                   ((in_ch <= 16'd256) && (in_w <= 16'd16) && (in_h <= 16'd16)) ||
                                   ((in_ch <= 16'd512) && (in_w <= 16'd8)  && (in_h <= 16'd8))); // FIX203_COMBO_MARGIN_K1RD64

    wire        k3_line_enable = // FIX205_K3_RD64_ACT_LINEFILL: row cache for k=3 small maps + selected k=1
                                 (((k_size == 4'd3) &&
                                   (((in_ch <= 16'd16)  && (in_w <= 16'd128) && (in_h <= 16'd128)) ||
                                    ((in_ch <= 16'd32)  && (in_w <= 16'd64)  && (in_h <= 16'd64))  ||
                                    ((in_ch <= 16'd64)  && (in_w <= 16'd32)  && (in_h <= 16'd32))  ||
                                    ((in_ch <= 16'd128) && (in_w <= 16'd16)  && (in_h <= 16'd16))  ||
                                    ((in_ch <= 16'd256) && (in_w <= 16'd8)   && (in_h <= 16'd8))) &&
                                   ((stride == 4'd1) || (stride == 4'd2))) ||
                                  ((k_size == 4'd1) && (stride == 4'd1) && (pad == 4'd0) &&
                                   (((in_ch <= 16'd64)  && (in_w <= 16'd64) && (in_h <= 16'd64)) ||
                                    ((in_ch <= 16'd128) && (in_w <= 16'd32) && (in_h <= 16'd32)) || // FIX208C_K1_128x32_ONLY
                                    ((in_ch <= 16'd256) && (in_w <= 16'd16) && (in_h <= 16'd16)) ||
                                    ((in_ch <= 16'd512) && (in_w <= 16'd8)  && (in_h <= 16'd8)))));
    wire       k3_fill64_enable = k3_line_enable && (k_size == 4'd3) && (in_w[2:0] == 3'd0); // FIX205_K3_RD64_ACT_LINEFILL
    wire       line_fill64_enable = k1_fill64_enable || k3_fill64_enable; // FIX205_K3_RD64_ACT_LINEFILL
    wire [15:0] k3_y_u = iy_calc[15:0];
    wire [7:0]  k3_x_u = ix_calc[7:0];
    wire [1:0]  k3_slot_w = iy_calc[1:0];
    wire [6:0]  k3_row_id_w = (ic[4:0] * K3_LINE_ROWS) + k3_slot_w;
    wire [14:0] k3_line_index_w = (k3_line_mode_w128_ch16 ? ({k3_row_id_w,7'd0} + k3_x_u) : ({k3_row_id_w,6'd0} + k3_x_u)); // FIX226B dynamic W
    wire        k3_line_active = k3_line_enable && in_bound && (ic < k3_line_ch_eff); // FIX226B dynamic CH limit
    wire        k3_line_hit = k3_line_active && k3_line_valid[k3_row_id_w] &&
                              (k3_line_tag_y[k3_row_id_w] == k3_y_u);
    wire        k3_line_miss = k3_line_active && !k3_line_hit;
    wire signed [7:0] k3_cached_act_s = k3_line_data[k3_line_index_w];

    wire [14:0] k3_fill_index = (k3_line_mode_w128_ch16 ? ({k3_fill_row_id,7'd0} + k3_fill_x) : ({k3_fill_row_id,6'd0} + k3_fill_x)); // FIX226B dynamic W
    wire [31:0] k3_fill_offset = (k3_fill_ic * (in_h * in_w)) +
                                  (k3_fill_y * in_w) + k3_fill_x;

    wire signed [7:0] line_cached_act_s = l0_line_active ? l0_cached_act_s : k3_cached_act_s; // FIX189E_MULTI_K3_ACT_LINEBUF

    wire [31:0] in_offset;
    wire [31:0] out_offset;
    wire [31:0] w_index;
    wire [31:0] lane_oc;
    wire [31:0] weight_tap_index;
    wire [31:0] weight_group_index;
    wire        lane_valid_current;
    wire        last_lane_current;

    assign lane_oc = oc + lane_idx;
    assign lane_valid_current = (lane_oc < out_ch);
    assign last_lane_current  = (lane_idx == (MAC_LANES-1)) || ((lane_oc + 32'd1) >= out_ch);

    assign in_offset  = ic * (in_h * in_w) + iy_calc * in_w + ix_calc;
    assign out_offset = lane_oc * (out_h * out_w) + oy * out_w + ox;

    // FIX164_MAC4_QUAD_WEIGHT_LAYOUT:
    // Original MAC1 layout is OC-major:
    //   weight[oc][ic][ky][kx]
    // Phase1 MAC4 reads 4 OC lanes for the same tap.  If we keep OC-major,
    // the 4 lane weights are far apart in DDR and cause many AXI/cache misses.
    // This layout stores weights as:
    //   group_oc4, tap, lane
    // with zero padding only for invalid tail lanes, so lane0..3 weights for a
    // tap are adjacent.  The bridge cache then serves lane1..3 as hits after
    // lane0 fetches the 64-bit line.
    assign weight_tap_index   = ((ic * k_size + ky) * k_size + kx);
    assign weight_group_index = oc / MAC_LANES;

    // FIX164_QUAD_SCOPE_DIAG: select original OC-major or MAC4 quad-interleaved index per op.
    wire [31:0] w_index_ocmajor;
    wire [31:0] w_index_quad;
    wire [31:0] w_index_quad_base; // FIX164_MAC4_WEIGHT_PACK32: address of packed lane0 byte
    wire        use_w4_read;       // FIX164_MAC4_WEIGHT_PACK32: MAC4 quad weights can be fetched as one 32-bit word
    wire        use_w8_read;       // FIX164_MAC8_VECTOR_PACK64: MAC8 oct weights can be fetched as one 64-bit word
    localparam integer W64_BEATS = (MAC_LANES + 7) / 8; // FIX164_MAC16_VECTOR_MULTIBEAT
    assign w_index_ocmajor  = (((lane_oc * in_ch + ic) * k_size + ky) * k_size + kx);
    assign w_index_quad_base = (((weight_group_index * (in_ch * k_size * k_size)) + weight_tap_index) * MAC_LANES);
    assign w_index_quad     = w_index_quad_base + lane_idx;
    assign w_index = quad_weight_en ? w_index_quad : w_index_ocmajor;
    assign use_w4_read = quad_weight_en && (MAC_LANES == 4);
    assign use_w8_read = quad_weight_en && (MAC_LANES >= 8); // FIX164_MAC16_VECTOR_MULTIBEAT: 64-bit multibeat path

    // FIX164_CONV_ALL_WEIGHT_CACHE: current oc-group weight span in the MAC16 packed layout.
    wire [31:0] wcache_taps_total       = in_ch * k_size * k_size;
    wire [31:0] wcache_total_bytes_w    = wcache_taps_total * MAC_LANES;
    wire [31:0] wcache_group_base_index = weight_group_index * wcache_total_bytes_w;
    wire        wcache_enable           = use_w8_read && (MAC_LANES == 64) && (wcache_total_bytes_w <= WCACHE_BYTES_MAX); // FIX182_MAC64_WCACHE_PACK512_NODUP
    wire        wcache_hit              = wcache_enable && wcache_valid && (wcache_oc == oc) && (wcache_total_beats == (wcache_total_bytes_w >> 3));

    wire [31:0] bias_next;
    assign bias_next = bias_r | ({24'd0, mem_rd_data} << (bias_byte_idx * 8));

    // FIX178_CONV_ACT_PREFETCH_WCACHE:
    // During the last cached-weight beat, issue the activation DDR read one cycle early.
    // If mem_rd_ready is high in that cycle, the FSM skips S_ACT_REQ and goes directly
    // to S_ACT_WAIT.  This attacks S_ACT_REQ without changing math/output layout.
    // FIX184_ACT_PREFETCH_SMAC:
    // After FIX182 the wcache use stage is only one cycle, so the old FIX178
    // activation prefetch is too late to hide much latency. Launch the
    // activation read one state earlier while S_MAC is selecting the cached
    // weight tap. If the bridge accepts it, S_WCACHE_USE_WAIT can go straight
    // to S_ACT_WAIT without spending S_ACT_REQ.
    reg  act_prefetch_pending;
    wire act_smac_prefetch_req;
    wire act_prefetch_req;
    assign act_smac_prefetch_req = (state == S_MAC) && in_bound && wcache_hit && !(l0_line_active || k3_line_active); // FIX185B_L0_INPUT_LINEBUF
    assign act_prefetch_req = (state == S_WCACHE_USE_WAIT) &&
                              !act_prefetch_pending && !(l0_line_active || k3_line_active) &&
                              (wcache_hit || (weight_beat_idx == (W64_BEATS-1))); // FIX185B_L0_INPUT_LINEBUF + FIX182

    assign mem_rd_req = (((state == S_BIAS_REQ) || (state == S_W_REQ)) && lane_valid_current) ||
                        (state == S_ACT_REQ) ||
                        (state == S_L0_FILL_REQ) || // FIX185B_L0_INPUT_LINEBUF
                        (state == S_K3_FILL_REQ) || // FIX189E_MULTI_K3_ACT_LINEBUF
                        act_smac_prefetch_req ||
                        act_prefetch_req; // FIX184_ACT_PREFETCH_SMAC + FIX178_CONV_ACT_PREFETCH_WCACHE
    assign mem_rd_addr = (state == S_BIAS_REQ)    ? (bias_base + (lane_oc * 4) + bias_byte_idx) :
                         (state == S_W_REQ)       ? w_addr_pipe :
                         (state == S_L0_FILL_REQ) ? (input_base + l0_fill_offset) : // FIX185B_L0_INPUT_LINEBUF
                         (state == S_K3_FILL_REQ) ? (input_base + k3_fill_offset) : // FIX189E_MULTI_K3_ACT_LINEBUF
                                                     (input_base + in_offset);

    // FIX164_MAC4_WEIGHT_PACK32: packed MAC4 quad weight read.  Requires the corresponding
    // yolo_weights_ddr.bin generated from the correct MAC1 weight blob.
    assign mem_rd32_req  = (state == S_W4_REQ);
    assign mem_rd32_addr = weight_base + w_index_quad_base;
    assign mem_rd64_req  = (state == S_W8_REQ) || (state == S_WCACHE_LOAD_REQ) || (state == S_K1_FILL64_REQ); // FIX201B_K1_LINEFILL_RD64
    assign mem_rd64_addr = (state == S_K1_FILL64_REQ) ? (input_base + k3_fill_offset) : // FIX201B_K1_LINEFILL_RD64
                           (state == S_WCACHE_LOAD_REQ) ?
                           (weight_base + wcache_group_base_index + (wcache_load_beat << 3)) :
                           (weight_base + w_index_quad_base + (weight_beat_idx * 8)); // FIX164_CONV_ALL_WEIGHT_CACHE

    wire signed [7:0] act_s;
    assign act_s = mem_rd_data;

    wire last_mac;
    assign last_mac = (ic == in_ch-1) && (ky == k_size-1) && (kx == k_size-1);

    wire last_output;
    assign last_output = ((oc + MAC_LANES) >= out_ch) && (oy == out_h-1) && (ox == out_w-1);

    wire signed [ACC_W-1:0] acc_current;
    assign acc_current = acc_vec[lane_idx];

    function lane_valid_f;
        input integer l;
        begin
            lane_valid_f = ((oc + l) < out_ch);
        end
    endfunction


    function signed [ACC_W-1:0] requant_mult_round;
        input signed [ACC_W-1:0] din;
        input [31:0] mult;
        input [4:0] sh;
        reg signed [63:0] prod;
        reg signed [63:0] mag;
        reg signed [63:0] rounded64;
        begin
            if (mult == 32'd0) begin
                requant_mult_round = din;
            end else begin
                prod = din * $signed({1'b0, mult});
                if (sh == 5'd0) begin
                    rounded64 = prod;
                end else if (prod >= 0) begin
                    rounded64 = (prod + (64'sd1 << (sh-1))) >>> sh;
                end else begin
                    mag = -prod;
                    rounded64 = -((mag + (64'sd1 << (sh-1))) >>> sh);
                end
                if (rounded64 > 64'sd2147483647)
                    requant_mult_round = 32'sh7fffffff;
                else if (rounded64 < -64'sd2147483648)
                    requant_mult_round = -32'sd2147483648;
                else
                    requant_mult_round = rounded64[ACC_W-1:0];
            end
        end
    endfunction

    function [DATA_W-1:0] sat_i8;
        input signed [ACC_W-1:0] din;
        begin
            if (din < -128)
                sat_i8 = 8'h80;
            else if (din > 127)
                sat_i8 = 8'h7f;
            else
                sat_i8 = din[7:0];
        end
    endfunction

    function signed [ACC_W-1:0] requant_round;
        input signed [ACC_W-1:0] din;
        input [4:0] sh;
        reg signed [ACC_W-1:0] mag;
        reg signed [ACC_W-1:0] rounded;
        begin
            if (sh == 5'd0) begin
                requant_round = din;
            end else if (din >= 0) begin
                requant_round = (din + ({{(ACC_W-1){1'b0}}, 1'b1} << (sh-1))) >>> sh;
            end else begin
                mag = -din;
                rounded = (mag + ({{(ACC_W-1){1'b0}}, 1'b1} << (sh-1))) >>> sh;
                requant_round = -rounded;
            end
        end
    endfunction

    // SiLU approximation for quantized signed-int8 values, Q4.4 domain.
    // Used after Conv+BN requant for normal YOLOv5 Conv blocks. Detect head remains linear.
