                8'hf4: silu_i8_direct_lut = 8'hfd;
                8'hf5: silu_i8_direct_lut = 8'hfd;
                8'hf6: silu_i8_direct_lut = 8'hfd;
                8'hf7: silu_i8_direct_lut = 8'hfd;
                8'hf8: silu_i8_direct_lut = 8'hfd;
                8'hf9: silu_i8_direct_lut = 8'hfd;
                8'hfa: silu_i8_direct_lut = 8'hfe;
                8'hfb: silu_i8_direct_lut = 8'hfe;
                8'hfc: silu_i8_direct_lut = 8'hfe;
                8'hfd: silu_i8_direct_lut = 8'hff;
                8'hfe: silu_i8_direct_lut = 8'hff;
                8'hff: silu_i8_direct_lut = 8'h00;
                endcase
            end
            default: silu_i8_direct_lut = silu_i8_q4_4(xin);
            endcase
        end
    endfunction
    // END AUTO DIRECT SILU LUT

    wire signed [ACC_W-1:0] acc_requant;
    wire [DATA_W-1:0]       acc_i8;
    assign acc_requant = (out_mult != 32'd0) ? requant_mult_round(acc_current, out_mult, out_mult_shift) : requant_round(acc_current, out_shift);
    assign acc_i8      = sat_i8(acc_requant);


    // Direct per-layer SiLU LUT: avoids Q4.4 intermediate saturation.
    wire [DATA_W-1:0]       silu_i8_direct;
    assign silu_i8_direct = silu_i8_direct_lut(silu_lut_id, acc_i8);

    // FIX213_WR_DATA_PREACC_PIPE:
    // Use registered accumulator for write-data generation to break
    // lane_idx -> acc_vec mux -> requant/silu -> wr_pipe_data path.
    wire signed [ACC_W-1:0] wr_acc_requant_pre;
    wire [DATA_W-1:0]       wr_acc_i8_pre;
    wire [DATA_W-1:0]       wr_silu_i8_direct_pre;
    assign wr_acc_requant_pre = (out_mult != 32'd0) ? requant_mult_round(wr_acc_pre, out_mult, out_mult_shift) : requant_round(wr_acc_pre, out_shift);
    assign wr_acc_i8_pre      = sat_i8(wr_acc_requant_pre);
    assign wr_silu_i8_direct_pre = silu_i8_direct_lut(silu_lut_id, wr_acc_i8_pre);
    // Scale-aware SiLU:
    // q44_x = round((q_conv * s_conv) / (1/16)) = round(q_conv * s_conv * 16)
    // q_out = round((silu_q44 / 16) / s_activation_out)
    wire signed [ACC_W-1:0] silu_q44_requant;
    wire [DATA_W-1:0]       silu_q44_i8;
    wire [DATA_W-1:0]       silu_q44_y_i8;
    wire signed [7:0]       silu_q44_y_s;
    wire signed [ACC_W-1:0] silu_qout_requant;
    wire [DATA_W-1:0]       silu_i8_scaled;
    assign silu_q44_requant = requant_mult_round(acc_requant, silu_in_mult, silu_in_shift);
    assign silu_q44_i8      = sat_i8(silu_q44_requant);
    assign silu_q44_y_i8    = silu_i8_q4_4(silu_q44_i8);
    assign silu_q44_y_s     = silu_q44_y_i8;
    assign silu_qout_requant = requant_mult_round({{(ACC_W-8){silu_q44_y_s[7]}}, silu_q44_y_s}, silu_out_mult, silu_out_shift);
    assign silu_i8_scaled   = sat_i8(silu_qout_requant);

    // FIX164_MAC16_WRITE_PREP_PIPE: write addr/data are registered in S_WRITE_PREP.
    assign mem_wr_req  = (state == S_WRITE) && wr_pipe_valid;
    assign mem_wr_addr = wr_pipe_addr;
    assign mem_wr_data = wr_pipe_data;

    // Enable only when output width is a multiple of 8, so no partial flush is needed.
    // All YOLO feature widths in this project are multiples of 8; fallback byte-write remains available.
    wire        conv_wr64_enable = (out_w[2:0] == 3'd0) && (out_w != 16'd0);
    wire [31:0] conv_wr64_flush_oc = oc + conv_wr64_flush_lane;
    wire        conv_wr64_flush_valid = (conv_wr64_flush_oc < out_ch);
    wire        conv_wr64_flush_last  = (conv_wr64_flush_lane == (MAC_LANES-1)) ||
                                        ((conv_wr64_flush_oc + 32'd1) >= out_ch);
    wire [31:0] conv_wr64_x_base = ox[31:0] - 32'd7;

    assign mem_wr64_req  = (state == S_WR64_FLUSH) && conv_wr64_flush_valid;
    assign mem_wr64_addr = output_base + (conv_wr64_flush_oc * (out_h * out_w)) +
                           (oy * out_w) + conv_wr64_x_base;
    assign mem_wr64_data = conv_wr64_buf[conv_wr64_flush_lane];

    assign final_wr_en   = mem_wr_req && mem_wr_ready;
    assign final_wr_addr = mem_wr_addr;
    assign final_wr_data = mem_wr_data;

    assign out_valid = final_wr_en;
    assign out_data  = acc_current;

    task advance_mac;
        begin
            if (kx == k_size-1) begin
                kx <= 0;
                if (ky == k_size-1) begin
                    ky <= 0;
                    if (ic == in_ch-1) begin
                        ic <= 0;
                    end else begin
                        ic <= ic + 1;
                    end
                end else begin
                    ky <= ky + 1;
                end
            end else begin
                kx <= kx + 1;
            end
        end
    endtask

    task advance_output;
        begin
            if (ox == out_w-1) begin
                ox <= 0;
                if (oy == out_h-1) begin
                    oy <= 0;
                    if ((oc + MAC_LANES) >= out_ch) begin
                        oc <= 0;
                    end else begin
                        oc <= oc + MAC_LANES;
                    end
                end else begin
                    oy <= oy + 1;
                end
            end else begin
                ox <= ox + 1;
            end
        end
    endtask

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            oc <= 0; oy <= 0; ox <= 0; ic <= 0; ky <= 0; kx <= 0;
            lane_idx <= 8'd0;
            bias_r <= 32'd0;
            bias_byte_idx <= 2'd0;
            wr_pipe_valid <= 1'b0; // FIX164_MAC16_WRITE_PREP_PIPE
            wr_pipe_addr <= {ADDR_W{1'b0}};
            wr_pipe_data <= {DATA_W{1'b0}};
            w_addr_pipe <= {ADDR_W{1'b0}};
                wr_acc_pre <= {ACC_W{1'b0}}; // FIX213_WR_DATA_PREACC_PIPE
            wr_out_byte_pre <= {DATA_W{1'b0}}; // FIX_CONV_WR64_PACKER_TIMING
            conv_wr64_flush_lane <= 8'd0; // FIX_CONV_WR64_PACKER
            l0_fill_x <= 9'd0; l0_fill_y <= 16'd0; l0_fill_ic <= 2'd0; l0_fill_slot <= 3'd0; l0_fill_row_id <= 5'd0; // FIX185B_L0_INPUT_LINEBUF
            k3_fill_x <= 8'd0; k3_fill_y <= 16'd0; k3_fill_ic <= 5'd0; k3_fill_slot <= 2'd0; k3_fill_row_id <= 7'd0; // FIX189E_MULTI_K3_ACT_LINEBUF
            k1_fill64_data <= 64'd0; k1_fill64_idx <= 3'd0; // FIX201B_K1_LINEFILL_RD64
            for (l0_reset_i = 0; l0_reset_i < L0_LINE_COUNT; l0_reset_i = l0_reset_i + 1) begin
                l0_line_valid[l0_reset_i] <= 1'b0;
                l0_line_tag_y[l0_reset_i] <= 16'd0;
            end
                          for (k3_reset_i = 0; k3_reset_i < K3_LINE_COUNT; k3_reset_i = k3_reset_i + 1) begin // FIX189E_MULTI_K3_ACT_LINEBUF
                              k3_line_valid[k3_reset_i] <= 1'b0;
                          end
            act_prefetch_pending <= 1'b0; // FIX184_ACT_PREFETCH_SMAC
            bias_cache_valid <= 1'b0; // FIX164_MAC16_BIAS_CACHE_SAFE
            bias_cache_oc <= 32'd0;
            for (lane_loop_i = 0; lane_loop_i < MAC_LANES; lane_loop_i = lane_loop_i + 1) begin
                acc_vec[lane_loop_i] <= {ACC_W{1'b0}};
                w_vec[lane_loop_i]   <= 8'sd0;
                bias_cache_vec[lane_loop_i] <= {ACC_W{1'b0}}; // FIX164_MAC16_BIAS_CACHE_SAFE
            end
        end else begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        oc <= 0;
                        oy <= 0;
                        ox <= 0;
                        ic <= 0;
                        ky <= 0;
                        kx <= 0;
                        lane_idx <= 8'd0;
                        bias_byte_idx <= 2'd0;
                        bias_r <= 32'd0;
                        wr_pipe_valid <= 1'b0; // FIX164_MAC16_WRITE_PREP_PIPE
                        wr_pipe_addr <= {ADDR_W{1'b0}};
                        wr_pipe_data <= {DATA_W{1'b0}};
                        w_addr_pipe <= {ADDR_W{1'b0}};
                wr_acc_pre <= {ACC_W{1'b0}}; // FIX213_WR_DATA_PREACC_PIPE
                        wr_out_byte_pre <= {DATA_W{1'b0}}; // FIX_CONV_WR64_PACKER_TIMING
                        conv_wr64_flush_lane <= 8'd0; // FIX_CONV_WR64_PACKER
                        bias_cache_valid <= 1'b0; // FIX164_MAC16_BIAS_CACHE_SAFE: new layer/op may use different bias_base
                        bias_cache_oc <= 32'd0;
                        wcache_valid <= 1'b0; // FIX164_CONV_ALL_WEIGHT_CACHE: new op may use different weight_base/shape
                        wcache_oc <= 32'd0;
                        wcache_total_beats <= 32'd0;
                        wcache_load_beat <= 32'd0;
                        for (l0_reset_i = 0; l0_reset_i < L0_LINE_COUNT; l0_reset_i = l0_reset_i + 1) begin // FIX185B_L0_INPUT_LINEBUF
                            l0_line_valid[l0_reset_i] <= 1'b0;
                        end
                        wcache_rd_beat <= 32'd0;
                        wcache_rd_data512 <= 512'd0; // FIX182_MAC64_WCACHE_PACK512_NODUP
                        act_prefetch_pending <= 1'b0; // FIX184_ACT_PREFETCH_SMAC
                        k1_fill64_data <= 64'd0; k1_fill64_idx <= 3'd0; // FIX201B_K1_LINEFILL_RD64
                        for (lane_loop_i = 0; lane_loop_i < MAC_LANES; lane_loop_i = lane_loop_i + 1) begin
                            acc_vec[lane_loop_i] <= {ACC_W{1'b0}};
                            w_vec[lane_loop_i]   <= 8'sd0;
                            bias_cache_vec[lane_loop_i] <= {ACC_W{1'b0}}; // FIX164_MAC16_BIAS_CACHE_SAFE
                        end
                        state <= S_BIAS_CHECK; // FIX164_MAC16_BIAS_CACHE_SAFE
                    end
                end

                // FIX164_MAC16_BIAS_CACHE_SAFE: if this output pixel uses the same OC group,
                // reload acc_vec from cached bias instead of re-reading MAC_LANES*4 bias bytes from DDR.
                S_BIAS_CHECK: begin
                    lane_idx <= 8'd0;
                    bias_byte_idx <= 2'd0;
                    bias_r <= 32'd0;
                    ic <= 0;
                    ky <= 0;
                    kx <= 0;
                    if (bias_cache_valid && (bias_cache_oc == oc)) begin
                        for (lane_loop_i = 0; lane_loop_i < MAC_LANES; lane_loop_i = lane_loop_i + 1) begin
                            acc_vec[lane_loop_i] <= bias_cache_vec[lane_loop_i];
                        end
                        state <= S_WCACHE_CHECK; // FIX164_CONV_ALL_WEIGHT_CACHE: ensure current oc-group weights are cached
                    end else begin
                        state <= S_BIAS_REQ;
                    end
                end

                // Read 32-bit bias for each valid lane in the current OC group.
                S_BIAS_REQ: begin
                    if (!lane_valid_current) begin
                        acc_vec[lane_idx] <= {ACC_W{1'b0}};
                        bias_cache_vec[lane_idx] <= {ACC_W{1'b0}}; // FIX164_MAC16_BIAS_CACHE_SAFE
                        bias_r <= 32'd0;
                        bias_byte_idx <= 2'd0;
                        if (last_lane_current) begin
                            lane_idx <= 8'd0;
                            ic <= 0;
                            ky <= 0;
                            kx <= 0;
                            bias_cache_valid <= 1'b1; // FIX164_MAC16_BIAS_CACHE_SAFE
                            bias_cache_oc <= oc;
                            state <= S_WCACHE_CHECK; // FIX164_CONV_ALL_WEIGHT_CACHE: ensure current oc-group weights are cached
                        end else begin
                            lane_idx <= lane_idx + 8'd1;
                            state <= S_BIAS_REQ;
                        end
                    end else if (mem_rd_ready) begin
                        state <= S_BIAS_WAIT;
                    end
                end

                S_BIAS_WAIT: begin
                    if (mem_rd_valid) begin
                        bias_r <= bias_next;
                        if (bias_byte_idx == 2'd3) begin
                            acc_vec[lane_idx] <= $signed(bias_next);
                            bias_cache_vec[lane_idx] <= $signed(bias_next); // FIX164_MAC16_BIAS_CACHE_SAFE
                            bias_r <= 32'd0;
                            bias_byte_idx <= 2'd0;
                            if (last_lane_current) begin
                                lane_idx <= 8'd0;
                                ic <= 0;
                                ky <= 0;
                                kx <= 0;
                                bias_cache_valid <= 1'b1; // FIX164_MAC16_BIAS_CACHE_SAFE
                                bias_cache_oc <= oc;
                                state <= S_WCACHE_CHECK; // FIX164_CONV_ALL_WEIGHT_CACHE: ensure current oc-group weights are cached
                            end else begin
                                lane_idx <= lane_idx + 8'd1;
                                state <= S_BIAS_REQ;
                            end
                        end else begin
                            bias_byte_idx <= bias_byte_idx + 1'b1;
                            state <= S_BIAS_REQ;
                        end
                    end
                end

                S_MAC: begin
                    if (in_bound) begin
                        lane_idx <= 8'd0;
                        if (wcache_hit) begin // FIX164_CONV_ALL_WEIGHT_CACHE: read current tap weights from on-chip cache
                            // FIX166_WCACHE_PREFETCH: launch cached beat0 during S_MAC itself.
                            // Old path: S_MAC -> USE_REQ0 -> USE_WAIT0 -> USE_REQ1 -> USE_WAIT1.
                            // New path: S_MAC/read0 -> USE_WAIT0/read1 -> USE_WAIT1.
                            // This keeps synchronous RAM style but removes two FSM cycles per tap.
                            weight_beat_idx <= 8'd0;
                            wcache_rd_beat <= weight_tap_index * W64_BEATS; // kept for debug/backward readability
                            wcache_rd_data512 <= wcache512[weight_tap_index]; // FIX182_MAC64_WCACHE_PACK512_NODUP
                            act_prefetch_pending <= mem_rd_ready; // FIX184_ACT_PREFETCH_SMAC: S_MAC launched act read
                            state <= S_WCACHE_USE_WAIT;
                        end else if (use_w8_read) begin // FIX164_MAC16_VECTOR_MULTIBEAT
                            weight_beat_idx <= 8'd0;
                            state <= S_W8_REQ;
                        end else begin
                            state <= use_w4_read ? S_W4_REQ : S_W_ADDR_PREP;
                        end
                    end else begin
                        if (last_mac) begin
                            lane_idx <= 8'd0;
                            state <= S_WRITE_PREP;
                        end else begin
                            advance_mac();
                            state <= S_MAC;
                        end
                    end
                end

                // FIX164_CONV_ALL_WEIGHT_CACHE: load/use current oc-group weights.
                S_WCACHE_CHECK: begin
                    if (wcache_hit) begin
                        state <= S_MAC;
                    end else if (wcache_enable) begin
                        wcache_valid <= 1'b0;
                        wcache_oc <= oc;
                        wcache_total_beats <= (wcache_total_bytes_w >> 3);
                        wcache_load_beat <= 32'd0;
                        state <= S_WCACHE_LOAD_REQ;
                    end else begin
                        state <= S_MAC;
                    end
                end

                S_WCACHE_LOAD_REQ: begin
                    if (mem_rd64_ready) begin
                        state <= S_WCACHE_LOAD_WAIT;
                    end
                end

                S_WCACHE_LOAD_WAIT: begin
                    if (mem_rd64_valid) begin
                        // FIX182_MAC64_WCACHE_PACK512_NODUP: pack 8 DDR64 beats into one MAC64 tap line.
                        case (wcache_load_beat[2:0])
                            3'd0: wcache512[wcache_load_beat[31:3]][ 63:  0] <= mem_rd64_data;
                            3'd1: wcache512[wcache_load_beat[31:3]][127: 64] <= mem_rd64_data;
                            3'd2: wcache512[wcache_load_beat[31:3]][191:128] <= mem_rd64_data;
                            3'd3: wcache512[wcache_load_beat[31:3]][255:192] <= mem_rd64_data;
                            3'd4: wcache512[wcache_load_beat[31:3]][319:256] <= mem_rd64_data;
                            3'd5: wcache512[wcache_load_beat[31:3]][383:320] <= mem_rd64_data;
                            3'd6: wcache512[wcache_load_beat[31:3]][447:384] <= mem_rd64_data;
                            3'd7: wcache512[wcache_load_beat[31:3]][511:448] <= mem_rd64_data;
                        endcase
                        if ((wcache_load_beat + 32'd1) >= wcache_total_beats) begin
                            wcache_valid <= 1'b1;
                            wcache_oc <= oc;
                            wcache_load_beat <= 32'd0;
                            state <= S_MAC;
                        end else begin
                            wcache_load_beat <= wcache_load_beat + 32'd1;
                            state <= S_WCACHE_LOAD_REQ;
                        end
                    end
                end

                S_WCACHE_USE_REQ: begin
                    // FIX182_MAC64_WCACHE_PACK512_NODUP: fallback entry; normally full tap is launched in S_MAC.
                    wcache_rd_data512 <= wcache512[weight_tap_index];
                    act_prefetch_pending <= 1'b0; // FIX184_ACT_PREFETCH_SMAC: fallback path has no S_MAC early read
                    state <= S_WCACHE_USE_WAIT;
                end

                S_WCACHE_USE_WAIT: begin
                    // FIX182_MAC64_WCACHE_PACK512_NODUP:
                    // One 512-bit cache line contains all 64 lane weights for this tap.
                    // Unpack all lanes in one FSM cycle instead of 8 cycles of 64-bit beats.
                    w_vec[0]  <= wcache_rd_data512[  7:  0];
                    w_vec[1]  <= wcache_rd_data512[ 15:  8];
                    w_vec[2]  <= wcache_rd_data512[ 23: 16];
                    w_vec[3]  <= wcache_rd_data512[ 31: 24];
                    w_vec[4]  <= wcache_rd_data512[ 39: 32];
                    w_vec[5]  <= wcache_rd_data512[ 47: 40];
                    w_vec[6]  <= wcache_rd_data512[ 55: 48];
                    w_vec[7]  <= wcache_rd_data512[ 63: 56];
                    w_vec[8]  <= wcache_rd_data512[ 71: 64];
                    w_vec[9]  <= wcache_rd_data512[ 79: 72];
                    w_vec[10] <= wcache_rd_data512[ 87: 80];
                    w_vec[11] <= wcache_rd_data512[ 95: 88];
                    w_vec[12] <= wcache_rd_data512[103: 96];
                    w_vec[13] <= wcache_rd_data512[111:104];
                    w_vec[14] <= wcache_rd_data512[119:112];
                    w_vec[15] <= wcache_rd_data512[127:120];
                    w_vec[16] <= wcache_rd_data512[135:128];
                    w_vec[17] <= wcache_rd_data512[143:136];
                    w_vec[18] <= wcache_rd_data512[151:144];
                    w_vec[19] <= wcache_rd_data512[159:152];
                    w_vec[20] <= wcache_rd_data512[167:160];
                    w_vec[21] <= wcache_rd_data512[175:168];
                    w_vec[22] <= wcache_rd_data512[183:176];
                    w_vec[23] <= wcache_rd_data512[191:184];
                    w_vec[24] <= wcache_rd_data512[199:192];
                    w_vec[25] <= wcache_rd_data512[207:200];
                    w_vec[26] <= wcache_rd_data512[215:208];
                    w_vec[27] <= wcache_rd_data512[223:216];
                    w_vec[28] <= wcache_rd_data512[231:224];
                    w_vec[29] <= wcache_rd_data512[239:232];
                    w_vec[30] <= wcache_rd_data512[247:240];
                    w_vec[31] <= wcache_rd_data512[255:248];
                    w_vec[32] <= wcache_rd_data512[263:256];
                    w_vec[33] <= wcache_rd_data512[271:264];
                    w_vec[34] <= wcache_rd_data512[279:272];
                    w_vec[35] <= wcache_rd_data512[287:280];
                    w_vec[36] <= wcache_rd_data512[295:288];
                    w_vec[37] <= wcache_rd_data512[303:296];
                    w_vec[38] <= wcache_rd_data512[311:304];
                    w_vec[39] <= wcache_rd_data512[319:312];
                    w_vec[40] <= wcache_rd_data512[327:320];
                    w_vec[41] <= wcache_rd_data512[335:328];
                    w_vec[42] <= wcache_rd_data512[343:336];
                    w_vec[43] <= wcache_rd_data512[351:344];
                    w_vec[44] <= wcache_rd_data512[359:352];
                    w_vec[45] <= wcache_rd_data512[367:360];
                    w_vec[46] <= wcache_rd_data512[375:368];
                    w_vec[47] <= wcache_rd_data512[383:376];
                    w_vec[48] <= wcache_rd_data512[391:384];
                    w_vec[49] <= wcache_rd_data512[399:392];
                    w_vec[50] <= wcache_rd_data512[407:400];
                    w_vec[51] <= wcache_rd_data512[415:408];
                    w_vec[52] <= wcache_rd_data512[423:416];
                    w_vec[53] <= wcache_rd_data512[431:424];
                    w_vec[54] <= wcache_rd_data512[439:432];
                    w_vec[55] <= wcache_rd_data512[447:440];
                    w_vec[56] <= wcache_rd_data512[455:448];
                    w_vec[57] <= wcache_rd_data512[463:456];
                    w_vec[58] <= wcache_rd_data512[471:464];
                    w_vec[59] <= wcache_rd_data512[479:472];
                    w_vec[60] <= wcache_rd_data512[487:480];
                    w_vec[61] <= wcache_rd_data512[495:488];
                    w_vec[62] <= wcache_rd_data512[503:496];
                    w_vec[63] <= wcache_rd_data512[511:504];
                    weight_beat_idx <= 8'd0;
                    lane_idx <= 8'd0;
                    if (l0_line_hit) begin
                        act_prefetch_pending <= 1'b0; // FIX185B_L0_INPUT_LINEBUF
                        state <= S_ACT_CACHE_HIT;
                    end else if (l0_line_miss) begin
                        // Fill the complete image row for this ic/y once, then use the cached pixel.
                        act_prefetch_pending <= 1'b0; // FIX185B_L0_INPUT_LINEBUF
                        l0_fill_x <= 9'd0;
                        l0_fill_y <= l0_y_u;
                        l0_fill_ic <= ic[1:0];
                        l0_fill_slot <= l0_slot_w;
                        l0_fill_row_id <= l0_row_id_w;
                        state <= S_L0_FILL_REQ;
                      end else if (k3_line_hit) begin // FIX189E_MULTI_K3_ACT_LINEBUF
                          act_prefetch_pending <= 1'b0;
                          state <= S_ACT_CACHE_HIT;
                      end else if (k3_line_miss) begin // FIX189E_MULTI_K3_ACT_LINEBUF
                          act_prefetch_pending <= 1'b0;
                          k3_fill_x <= 8'd0;
                          k3_fill_y <= k3_y_u;
                          k3_fill_ic <= ic[4:0];
                          k3_fill_slot <= k3_slot_w;
                          k3_fill_row_id <= k3_row_id_w;
                          k1_fill64_idx <= 3'd0; // FIX201B_K1_LINEFILL_RD64
                          state <= line_fill64_enable ? S_K1_FILL64_REQ : S_K3_FILL_REQ; // FIX205_K3_RD64_ACT_LINEFILL
                    end else if (act_prefetch_pending) begin
                        state <= S_ACT_WAIT; // FIX184_ACT_PREFETCH_SMAC: act request already accepted in S_MAC
                    end else begin
                        act_prefetch_pending <= mem_rd_ready; // FIX184_ACT_PREFETCH_SMAC: old FIX178 request accepted here
                        state <= mem_rd_ready ? S_ACT_WAIT : S_ACT_REQ; // preserve FIX178 early activation request
                    end
                end

                // FIX164_MAC8_VECTOR_PACK64: fast path for MAC8 oct-interleaved weights.
                // One 64-bit read returns w_vec[0..7] for the current tap.
                S_W8_REQ: begin
                    if (mem_rd64_ready) begin
                        state <= S_W8_WAIT;
                    end
                end

                S_W8_WAIT: begin
                    if (mem_rd64_valid) begin
                        // FIX180_FULL_MAC64_GROUP64: generic fallback unpack for MAC16/32/64.
                        case (weight_beat_idx)
                            8'd0: begin
                        w_vec[0] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 1) w_vec[1] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 2) w_vec[2] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 3) w_vec[3] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 4) w_vec[4] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 5) w_vec[5] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 6) w_vec[6] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 7) w_vec[7] <= mem_rd64_data[63:56];
                            end
                            8'd1: begin
                        if (MAC_LANES > 8) w_vec[8] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 9) w_vec[9] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 10) w_vec[10] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 11) w_vec[11] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 12) w_vec[12] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 13) w_vec[13] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 14) w_vec[14] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 15) w_vec[15] <= mem_rd64_data[63:56];
                            end
                            8'd2: begin
                        if (MAC_LANES > 16) w_vec[16] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 17) w_vec[17] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 18) w_vec[18] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 19) w_vec[19] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 20) w_vec[20] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 21) w_vec[21] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 22) w_vec[22] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 23) w_vec[23] <= mem_rd64_data[63:56];
                            end
                            8'd3: begin
                        if (MAC_LANES > 24) w_vec[24] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 25) w_vec[25] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 26) w_vec[26] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 27) w_vec[27] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 28) w_vec[28] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 29) w_vec[29] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 30) w_vec[30] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 31) w_vec[31] <= mem_rd64_data[63:56];
                            end
                            8'd4: begin
                        if (MAC_LANES > 32) w_vec[32] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 33) w_vec[33] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 34) w_vec[34] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 35) w_vec[35] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 36) w_vec[36] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 37) w_vec[37] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 38) w_vec[38] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 39) w_vec[39] <= mem_rd64_data[63:56];
                            end
                            8'd5: begin
                        if (MAC_LANES > 40) w_vec[40] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 41) w_vec[41] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 42) w_vec[42] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 43) w_vec[43] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 44) w_vec[44] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 45) w_vec[45] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 46) w_vec[46] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 47) w_vec[47] <= mem_rd64_data[63:56];
                            end
                            8'd6: begin
                        if (MAC_LANES > 48) w_vec[48] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 49) w_vec[49] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 50) w_vec[50] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 51) w_vec[51] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 52) w_vec[52] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 53) w_vec[53] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 54) w_vec[54] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 55) w_vec[55] <= mem_rd64_data[63:56];
                            end
                            8'd7: begin
                        if (MAC_LANES > 56) w_vec[56] <= mem_rd64_data[7:0];
                        if (MAC_LANES > 57) w_vec[57] <= mem_rd64_data[15:8];
                        if (MAC_LANES > 58) w_vec[58] <= mem_rd64_data[23:16];
                        if (MAC_LANES > 59) w_vec[59] <= mem_rd64_data[31:24];
                        if (MAC_LANES > 60) w_vec[60] <= mem_rd64_data[39:32];
                        if (MAC_LANES > 61) w_vec[61] <= mem_rd64_data[47:40];
                        if (MAC_LANES > 62) w_vec[62] <= mem_rd64_data[55:48];
                        if (MAC_LANES > 63) w_vec[63] <= mem_rd64_data[63:56];
                            end
                            default: begin end
                        endcase
                        if (weight_beat_idx == (W64_BEATS-1)) begin
                            weight_beat_idx <= 8'd0;
                            lane_idx <= 8'd0;
                            state <= S_ACT_REQ;
                        end else begin
                            weight_beat_idx <= weight_beat_idx + 8'd1;
                            state <= S_W8_REQ;
                        end
                    end
                end

                // FIX164_MAC4_WEIGHT_PACK32: fast path for MAC4 quad-interleaved weights.
                // One 32-bit read returns w_vec[0..3] for the current tap.
                S_W4_REQ: begin
                    if (mem_rd32_ready) begin
                        state <= S_W4_WAIT;
                    end
                end

                S_W4_WAIT: begin
                    if (mem_rd32_valid) begin
                        w_vec[0] <= mem_rd32_data[7:0];
                        w_vec[1] <= mem_rd32_data[15:8];
                        w_vec[2] <= mem_rd32_data[23:16];
                        w_vec[3] <= mem_rd32_data[31:24];
                        lane_idx <= 8'd0;
                        state <= S_ACT_REQ;
                    end
                end

                // Read one weight per valid lane. Input activation is read only once after all weights are ready.
                S_W_ADDR_PREP: begin
                    // w_index contains several dependent multiplies.  Give it
                    // a full cycle to settle, then hold the resulting address
                    // stable for the complete request/ready handshake.
                    w_addr_pipe <= weight_base + w_index;
                    state <= S_W_REQ;
                end

                S_W_REQ: begin
                    if (!lane_valid_current) begin
                        w_vec[lane_idx] <= 8'sd0;
                        if (last_lane_current) begin
                            lane_idx <= 8'd0;
                            state <= S_ACT_REQ;
                        end else begin
                            lane_idx <= lane_idx + 8'd1;
                            state <= S_W_ADDR_PREP;
                        end
                    end else if (mem_rd_ready) begin
                        state <= S_W_WAIT;
                    end
                end

                S_W_WAIT: begin
                    if (mem_rd_valid) begin
                        w_vec[lane_idx] <= mem_rd_data;
                        if (last_lane_current) begin
                            lane_idx <= 8'd0;
                            state <= S_ACT_REQ;
                        end else begin
                            lane_idx <= lane_idx + 8'd1;
                            state <= S_W_ADDR_PREP;
                        end
                    end
                end

                // FIX185B_L0_INPUT_LINEBUF: fill one 320-byte input image row into the rolling L0 line buffer.
                S_L0_FILL_REQ: begin
                    if (mem_rd_ready) begin
                        state <= S_L0_FILL_WAIT;
                    end
                end

                S_L0_FILL_WAIT: begin
                    if (mem_rd_valid) begin
                        l0_line_data[l0_fill_index] <= mem_rd_data;
                        if (l0_fill_x == (L0_LINE_W-1)) begin
                            l0_line_tag_y[l0_fill_row_id] <= l0_fill_y;
                            l0_line_valid[l0_fill_row_id] <= 1'b1;
                            l0_fill_x <= 9'd0;
                            state <= S_ACT_CACHE_HIT;
                        end else begin
                            l0_fill_x <= l0_fill_x + 9'd1;
                            state <= S_L0_FILL_REQ;
                        end
                    end
                end

                // FIX189E_MULTI_K3_ACT_LINEBUF: fill one activation row for selected k=3 convs.
                S_K3_FILL_REQ: begin
                    if (mem_rd_ready) begin
                        state <= S_K3_FILL_WAIT;
                    end
                end

                S_K3_FILL_WAIT: begin
                    if (mem_rd_valid) begin
                        k3_line_data[k3_fill_index] <= mem_rd_data;
                        if (k3_fill_x == (in_w[7:0] - 8'd1)) begin
                            k3_line_tag_y[k3_fill_row_id] <= k3_fill_y;
                            k3_line_valid[k3_fill_row_id] <= 1'b1;
                            k3_fill_x <= 8'd0;
                            state <= S_ACT_CACHE_HIT;
                        end else begin
                            k3_fill_x <= k3_fill_x + 8'd1;
                            state <= S_K3_FILL_REQ;
                        end
                    end
                end

                // FIX205_K3_RD64_ACT_LINEFILL:
                // Shared K1/K3 linefill. Use one RD64 beat to fetch 8 consecutive x bytes,
                // then drain them into the existing row cache one byte per cycle. This avoids
                // 8 separate DDR RD8 handshakes while preserving the old CHW layout/output.
                S_K1_FILL64_REQ: begin
                    if (mem_rd64_ready) begin
                        state <= S_K1_FILL64_WAIT;
                    end
                end

                S_K1_FILL64_WAIT: begin
                    if (mem_rd64_valid) begin
                        k1_fill64_data <= mem_rd64_data;
                        k1_fill64_idx <= 3'd0;
                        state <= S_K1_FILL64_DRAIN;
                    end
                end

                S_K1_FILL64_DRAIN: begin
                    case (k1_fill64_idx)
                        3'd0: k3_line_data[k3_fill_index] <= k1_fill64_data[ 7: 0];
                        3'd1: k3_line_data[k3_fill_index] <= k1_fill64_data[15: 8];
                        3'd2: k3_line_data[k3_fill_index] <= k1_fill64_data[23:16];
                        3'd3: k3_line_data[k3_fill_index] <= k1_fill64_data[31:24];
                        3'd4: k3_line_data[k3_fill_index] <= k1_fill64_data[39:32];
                        3'd5: k3_line_data[k3_fill_index] <= k1_fill64_data[47:40];
                        3'd6: k3_line_data[k3_fill_index] <= k1_fill64_data[55:48];
                        3'd7: k3_line_data[k3_fill_index] <= k1_fill64_data[63:56];
                    endcase

                    if (k3_fill_x == (in_w[7:0] - 8'd1)) begin
                        k3_line_tag_y[k3_fill_row_id] <= k3_fill_y;
                        k3_line_valid[k3_fill_row_id] <= 1'b1;
                        k3_fill_x <= 8'd0;
                        k1_fill64_idx <= 3'd0;
                        state <= S_ACT_CACHE_HIT;
                    end else begin
                        k3_fill_x <= k3_fill_x + 8'd1;
                        if (k1_fill64_idx == 3'd7) begin
                            k1_fill64_idx <= 3'd0;
                            state <= S_K1_FILL64_REQ;
                        end else begin
                            k1_fill64_idx <= k1_fill64_idx + 3'd1;
                            state <= S_K1_FILL64_DRAIN;
                        end
                    end
                end

                S_ACT_CACHE_HIT: begin
                    // Same math as S_ACT_WAIT, but activation byte comes from a local line buffer.
                    act_prefetch_pending <= 1'b0;
                    for (lane_loop_i = 0; lane_loop_i < MAC_LANES; lane_loop_i = lane_loop_i + 1) begin
                        if (lane_valid_f(lane_loop_i)) begin
                            acc_vec[lane_loop_i] <= acc_vec[lane_loop_i] + (line_cached_act_s * w_vec[lane_loop_i]);
                        end
                    end
                    if (last_mac) begin
                        lane_idx <= 8'd0;
                        state <= S_WRITE_PREP;
                    end else begin
                        advance_mac();
                        state <= S_MAC;
                    end
                end

                S_ACT_REQ: begin
                    if (mem_rd_ready) begin
                        act_prefetch_pending <= 1'b1; // FIX184_ACT_PREFETCH_SMAC: normal act request accepted
                        state <= S_ACT_WAIT;
                    end
                end

                S_ACT_WAIT: begin
                    if (mem_rd_valid) begin
                        act_prefetch_pending <= 1'b0; // FIX184_ACT_PREFETCH_SMAC
                        for (lane_loop_i = 0; lane_loop_i < MAC_LANES; lane_loop_i = lane_loop_i + 1) begin
                            if (lane_valid_f(lane_loop_i)) begin
                                acc_vec[lane_loop_i] <= acc_vec[lane_loop_i] + (act_s * w_vec[lane_loop_i]);
                            end
                        end
                        if (last_mac) begin
                            lane_idx <= 8'd0;
                            state <= S_WRITE_PREP;
                        end else begin
                            advance_mac();
                            state <= S_MAC;
                        end
                    end
                end

                // Sequential writer over valid lanes. No S_WRITE0..S_WRITE127 explosion.
                // FIX164_MAC16_WRITE_PREP_PIPE:
                //   S_WRITE_PREP registers the requant/SiLU output and output address.
                //   S_WRITE only handshakes the already-registered byte into the bridge.
                // This cuts the long timing path from lane_idx/acc/requant/SiLU to u_bridge/wr_data_r.
                S_WRITE_PREP: begin
                    wr_pipe_valid <= 1'b0;
                    if (!lane_valid_current) begin
                        if (last_lane_current) begin
                            if (last_output) begin
                                state <= S_DONE;
                            end else begin
                                advance_output();
                                lane_idx <= 8'd0;
                                bias_byte_idx <= 2'd0;
                                bias_r <= 32'd0;
                                state <= S_BIAS_CHECK; // FIX164_MAC16_BIAS_CACHE_SAFE
                            end
                        end else begin
                            lane_idx <= lane_idx + 8'd1;
                            state <= S_WRITE_PREP;
                        end
                    end else begin
                        wr_acc_pre    <= acc_current; // FIX213_WR_DATA_PREACC_PIPE
                        wr_pipe_valid <= 1'b0;
                        if (!conv_wr64_enable) begin
                            wr_pipe_addr <= output_base + out_offset;
                        end
                        state <= S_WRITE_PREP2;
                    end
                end

                S_WRITE_PREP2: begin // FIX213_WR_DATA_PREACC_PIPE
                    // FIX_CONV_WR64_PACKER_TIMING:
                    // Register the final 8-bit output before writing conv_wr64_buf.
                    // This cuts the failing path wr_acc_pre/active_conv_mult -> RAM W_DATA.
                    wr_out_byte_pre <= act_silu_en ? wr_silu_i8_direct_pre : wr_acc_i8_pre;
                    state <= S_WRITE_PREP3;
                end

                S_WRITE_PREP3: begin // FIX_CONV_WR64_PACKER_TIMING
                    if (conv_wr64_enable) begin
                        // Pack the registered byte into the slot for current x.
                        case (ox[2:0])
                            3'd0: conv_wr64_buf[lane_idx][ 7: 0] <= wr_out_byte_pre;
                            3'd1: conv_wr64_buf[lane_idx][15: 8] <= wr_out_byte_pre;
                            3'd2: conv_wr64_buf[lane_idx][23:16] <= wr_out_byte_pre;
                            3'd3: conv_wr64_buf[lane_idx][31:24] <= wr_out_byte_pre;
                            3'd4: conv_wr64_buf[lane_idx][39:32] <= wr_out_byte_pre;
                            3'd5: conv_wr64_buf[lane_idx][47:40] <= wr_out_byte_pre;
                            3'd6: conv_wr64_buf[lane_idx][55:48] <= wr_out_byte_pre;
                            3'd7: conv_wr64_buf[lane_idx][63:56] <= wr_out_byte_pre;
                        endcase

                        if (last_lane_current) begin
                            if (ox[2:0] == 3'd7) begin
                                conv_wr64_flush_lane <= 8'd0;
                                state <= S_WR64_FLUSH;
                            end else begin
                                advance_output();
                                lane_idx <= 8'd0;
                                bias_byte_idx <= 2'd0;
                                bias_r <= 32'd0;
                                state <= S_BIAS_CHECK;
                            end
                        end else begin
                            lane_idx <= lane_idx + 8'd1;
                            state <= S_WRITE_PREP;
                        end
                    end else begin
                        wr_pipe_data  <= wr_out_byte_pre;
                        wr_pipe_valid <= 1'b1;
                        state <= S_WRITE;
                    end
                end

                S_WRITE: begin
                    if (wr_pipe_valid && mem_wr_ready) begin
                        wr_pipe_valid <= 1'b0;
                        if (last_lane_current) begin
                            if (last_output) begin
                                state <= S_DONE;
                            end else begin
                                advance_output();
                                lane_idx <= 8'd0;
                                bias_byte_idx <= 2'd0;
                                bias_r <= 32'd0;
                                state <= S_BIAS_CHECK; // FIX164_MAC16_BIAS_CACHE_SAFE
                            end
                        end else begin
                            lane_idx <= lane_idx + 8'd1;
                            state <= S_WRITE_PREP;
                        end
                    end
                end

                S_WR64_FLUSH: begin // FIX_CONV_WR64_PACKER
                    if (conv_wr64_flush_valid && !mem_wr64_ready) begin
                        state <= S_WR64_FLUSH;
                    end else begin
                        if (conv_wr64_flush_last) begin
                            conv_wr64_flush_lane <= 8'd0;
                            if (last_output) begin
                                state <= S_DONE;
                            end else begin
                                advance_output();
                                lane_idx <= 8'd0;
                                bias_byte_idx <= 2'd0;
                                bias_r <= 32'd0;
                                state <= S_BIAS_CHECK;
                            end
                        end else begin
                            conv_wr64_flush_lane <= conv_wr64_flush_lane + 8'd1;
                            state <= S_WR64_FLUSH;
                        end
                    end
                end

                S_DONE: begin
                    state <= S_IDLE;
                end

                default: begin
                    state <= S_IDLE;
                end
            endcase
        end
    end

endmodule
